  eventType: string, 
  data: TRequest, 
  timeoutMs: number = 5000
): Promise<TResponse> {
  return new Promise((resolve, reject) => {
    const responseEvent = `${eventType}.response`
    let settled = false
    const timer = setTimeout(() => {
      if (!settled) {
        settled = true
        reject(new Error(`Request timeout: ${eventType}`))
